	call_if_exists(main, "sound_alarm")
	await wait_frames(2)

	var enemies := get_tree().get_nodes_in_group("enemies")
	var all_alerted := true
	for enemy in enemies:
		var alerted = get_prop(enemy, "is_alerted")
		if alerted != true:
			all_alerted = false
			break
	check("alarm_called", all_alerted, "sound_alarm() deve impostare is_alerted a true su tutti i nodi del gruppo enemies")

	var closest_enemy = call_if_exists(main, "find_closest_enemy", [Vector2(110.0, 100.0)])
	var enemy_1 := find_by_name(main, "Enemy1")
	check("finds_correct_closest", closest_enemy == enemy_1, "Il nemico più vicino al punto (110, 100) deve essere Enemy1")
