func find_closest_enemy(point: Vector2) -> Node2D:
	var enemies: Array[Node] = get_tree().get_nodes_in_group("enemies")
	var closest: Node2D = null
	var min_distance: float = INF

	for node in enemies:
		var enemy := node as Node2D
		if enemy == null:
			continue
		var dist: float = enemy.position.distance_to(point)
		if dist < min_distance:
			min_distance = dist
			closest = enemy

	return closest
